function _opsFitBoard() {
  const tab = document.getElementById('tab-ops');
  if (!tab) return;
  if (!window._opsFitBound) {
    window._opsFitBound = true;
    window.addEventListener('resize', function () {
      if (window._opsFitTimer) clearTimeout(window._opsFitTimer);
      window._opsFitTimer = setTimeout(_opsFitBoard, 80);
    });
  }
  const nCheck = (_opsRows || []).filter(function (r) { return !r.isCheckinOnly; }).length;
  const extras = (typeof _opsCleanDayInfo === 'function') ? ((_opsCleanDayInfo().extras || []).length) : 0;
  const n = Math.max(1, nCheck + extras);
  const bar = tab.querySelector('.opsx-bar');
  const share = document.getElementById('ops-crew-share-bar');
  const attn = tab.querySelector('.opsx-attn');
  const head = tab.querySelector('#ops-shot-ops .opsx-bhd');
  const thead = tab.querySelector('#ops-shot-ops thead');
  let chrome = 28;
  [bar, share, attn, head, thead].forEach(function (el) {
    if (el) chrome += el.offsetHeight || 0;
  });
  const vh = window.innerHeight || 800;
  const avail = Math.max(200, vh - chrome);
  const dense = n >= 10 || (avail / n) < 36;
  const rowH = Math.max(22, Math.min(dense ? 36 : 46, Math.floor(avail / n)));
  const fs = rowH >= 36 ? 12 : rowH >= 28 ? 11 : 10;
  const pad = Math.max(1, Math.min(6, Math.floor(rowH / 8)));
  tab.style.setProperty('--ops-row-h', rowH + 'px');
  tab.style.setProperty('--ops-fs', fs + 'px');
  tab.style.setProperty('--ops-pad', pad + 'px');
  tab.classList.toggle('ox-dense', dense || rowH < 34);
  tab.classList.add('ox-fit');
}

